*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS05500.xml';
scwin.vMktactCd = '320';
scwin.vIsuCd = '', scwin.vCheck_DuplCnt = '', scwin.hasAttachDoc = '';
scwin.gBndApplId = '', scwin.gProcsStat = '';
scwin.vBndListProcsTpCd = 1; //채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp; //접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9
scwin.btnStat = new Object();
scwin.vViewYN = 'N';
scwin.vRowPos = 0;
scwin.vRetRow = 0, scwin.vRetRowApplCnt = 0;
scwin.objRowPos = new Object();
scwin.vSaleRow = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 목록조회
 ***********************************************/
scwin.fn_list_sync = function() {
    $c.cm.setColumnProp(grd_List2, "CHK", "headcheck", false);
    var dsNm = 'BNS_APPL_ACPT_LIST';
    var qryId = '';
    if (scwin.vBndListProcsTpCd == 2) {
        qryId = 'lds.stf.bnsisuchg.select.listAcpt';
    } else {
        qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
    }
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd == 1) {
        $c.cm.ShowWin(grd_List1);
    } else {
        $c.cm.ShowWin(grd_List2);
    }
};



/********************************************** 
 * 함수명  	 : fn_dtl_sync
 * 설명       : 상세조회
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var dsNm = 'BNS_ISU_CHG_INFO';
    var qryId = '';
    var param = '';
    if (scwin.vBndListProcsTpCd == 1) {
        qryId = 'lds.stf.bnsisuchg.select.readIsuChgInfoAmtMmDdAdd';
        param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
        param += '&{P}V_BND_APPL_ID=' + scwin.gBndApplId;
        param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    }
    if (scwin.vBndListProcsTpCd == 2) {
        qryId = 'lds.stf.bnsisuchg.select.readIsuChgInfoAmtDdAppl';
        param += '&{P}V_ISU_CD=' + scwin.vIsuCd;
        var vStrtDd = dts_List.getCellData(dts_List.getRowPosition(), "STRT_DD");
        param += '&{P}V_STRT_DD=' + vStrtDd;
    }
    param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명  	 : fn_sales_sync
 * 설명       : 매출기관별 매출내역 조회
 ***********************************************/
scwin.fn_sales_sync = function() {
    var dsNm = 'BNS_SALES_DESC';
    var qryId = 'lds.stf.bnsisuchg.select.listSalesDesc';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_ISU_CD=' + scwin.vIsuCd;
    var vStrtDd = dts_List.getCellData(dts_List.getRowPosition(), "STRT_DD");
    param += '&{P}V_STRT_DD=' + vStrtDd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SalesList, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    if (scwin.vBndListProcsTpCd == 1) {
        if ($c.stf.getObjectValue(edt_StrtDd) == '') {
            $c.win.alert("[적용일]을 입력하십시오.");
            edt_StrtDd.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_StrtDd, "적용일")) {
            return false;
        }
        if ($c.stf.getObjectValue(edt_SaleDd) == '') {
            $c.win.alert("[매출일]을 입력하십시오.");
            edt_SaleDd.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_SaleDd, "매출일")) {
            return false;
        }
        if ($c.stf.getObjectValue(edt_BndSaleTotamt) == '') {
            $c.win.alert("[일중 매출총액]을 입력하십시오.");
            edt_BndSaleTotamt.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_RedmptAmt) == '') {
            $c.win.alert("[일중 중도상환액]을 입력하십시오.");
            edt_RedmptAmt.focus();
            return false;
        }
    } else {
        if ($c.stf.getObjectValue(edt_StrtDd2) == '') {
            $c.win.alert("[적용일]을 입력하십시오.");
            edt_StrtDd2.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_StrtDd2, "적용일")) {
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_ApplCntCheckInstDupl jackal_200320
 * 설명       : 동일종목에 대한 동일매출기관, 동일 매출일이 접수내역에 있는지 체크
 ***********************************************/
scwin.fn_ApplCntCheckInstDupl = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_COM_CD";
    url += "&queryId=lds.stf.bnsisuchg.select.acptApplCntCheckInstCdSaleDd";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_ISU_CD=" + dts_DtlInfo.getCellData(1, "ISU_CD");
    url += "&{P}V_BND_INST_CD=" + dts_DtlInfo.getCellData(1, "BND_INST_CD");
    url += "&{P}V_SALE_DD=" + dts_DtlInfo.getCellData(1, "SALE_DD");
    dts_CheckCnt.SyncLoad = "true";
    dts_CheckCnt.DataID = encodeURI(url);
    dts_CheckCnt.Reset();
    return dts_CheckCnt.getCellData(1, "TEXT");
};


/********************************************** 
 * 함수명   : fn_SameIsuOtherAcptYN
 * 설명       : 동일종목에 대한 적용일이 다른 접수내역에 있는지 체크
 ***********************************************/
scwin.fn_SameIsuOtherAcptYN = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_COM_CD";
    url += "&queryId=lds.stf.bnsisuchg.select.checkAcptDupl";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //url += "&{P}V_ISU_CD="+ dts_List.NameValue(1, "ISU_CD");  클릭한 종목코드를 가져오지 못하는 버그 수정	jackal_200320 
    url += "&{P}V_ISU_CD=" + dts_List.getCellData(dts_List.getRowPosition(), "ISU_CD");
    dts_CheckCnt.SyncLoad = "true";
    dts_CheckCnt.DataID = encodeURI(url);
    dts_CheckCnt.Reset();
    return dts_CheckCnt.getCellData(1, "TEXT");
};


/********************************************** 
 * 함수명   : fn_TeamLeaderOrProcsCnt
 * 설명       : 팀장확인된/처리완료된 종목이 있는가 체크
 ***********************************************/
scwin.fn_TeamLeaderOrProcsCnt = function(teamleadOrProcs) {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_COM_CD";
    url += "&queryId=lds.stf.bnsisuchg.select.checkTeamLeaderCnt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_V_TEAM_OR_PROCS=" + teamleadOrProcs;
    url += "&{P}V_ISU_CD=" + scwin.vIsuCd;
    url += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_StrtDd2);
    dts_CheckCnt.SyncLoad = "true";
    dts_CheckCnt.DataID = encodeURI(url);
    dts_CheckCnt.Reset();
    return dts_CheckCnt.getCellData(1, "TEXT");
};


/******************************************************************* 
 * 함수명   : fn_DdPackTeamleadrConfrm -사용안함
 * 설명     : (일별금액조정 전용) 팀장확인을 처리한다.
 * argument : vScrenID, trsObj, confrmDd, vAllBndApplId, vBndListProcsTpCd
 *******************************************************************/
scwin.fn_DdPackTeamleadrConfrm = function(vScrenID, trsObj, confrmDd, vAllBndApplId, vBndListProcsTpCd) {
    //담당자는 팀장확인 안됨.
    if (js_jobtitl == '03') {
        $c.win.alert('팀장권한만 가능합니다.');
        return;
    }
    if (confrmDd != "undefined" && confrmDd != '-' && confrmDd != '') {
        if (!window.confirm("이미 팀장확인처리되었습니다. 재처리하실경우 다시 시장지파일이 전송됩니다. \n 팀장확인처리하시겠습니까?")) return;
    } else {
        if (!window.confirm("팀장확인처리일자가 시장지파일 전송일자입니다. \n 팀장확인처리하시겠습니까?")) return;
    }
    dts_Temp.UseChangeInfo = "False";
    var url = "/bns/IsuChgAmt.do?method=processTeamleadrConfrm";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&ALL_BND_APPL_ID=" + vAllBndApplId;
    url += "&BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    trsObj.Action = $c.lc.fn_encodeNSession(url);
    trsObj.KeyName = "toinb_dataid4";
    trsObj.KeyValue = "JSP(I:pInput=dts_Temp)";
    trsObj.Post();
};


/********************************************** 
 * 함수명   : fn_ApplCntCheck
 * 설명       : 접수내역의 신청건수 체크
 ***********************************************/
scwin.fn_ApplCntCheck = function(dtsObj) {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_COM_CD";
    url += "&queryId=lds.stf.bnsisuchg.select.acptApplCntCheck";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_ISU_CD=" + scwin.vIsuCd;
    dts_CheckCnt.SyncLoad = "true";
    dts_CheckCnt.DataID = encodeURI(url);
    dts_CheckCnt.Reset();
    return dts_CheckCnt.getCellData(1, "TEXT");
};


/********************************************** 
 * 함수명   : fn_AcptProcsCheck
 * 설명      : 접수, 처리완료시 공통 체크 구문
 ***********************************************/
scwin.fn_AcptProcsCheck = function(gubun) {
    //필수입력값 체크
    if (scwin.fn_InputCheck() == false) return 1;
    if (gubun == 'Acpt') {
        //적용일,매매일,마감일,채권마감 체크		
        if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.gBndApplId) > 0) return 1;
    } else if (gubun == 'Procs') {
        //적용일,매매일,마감일,채권마감 체크		
        if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd2), scwin.gBndApplId) > 0) return 1;
    }
    scwin.vIsuCd = dts_DtlInfo.getCellData(1, "ISU_CD");
    scwin.hasAttachDoc = dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC");

    //변경된 데이터가 없더라도 데이터셋 전송
    dts_DtlInfo.UseChangeInfo = "False";
    return 0;
};


/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 신청데이터를 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck('Acpt') > 0) return;

    //복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRule(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd)) > 0) return;

    //접수내역의 신청건수 체크		
    if (scwin.fn_ApplCntCheck() > 0) {
        // 동일종목,동일매출기관,동일매출일이 접수내역에 있는제 체크 jackal_200320
        if (scwin.fn_ApplCntCheckInstDupl() > 0) {
            $c.win.alert("동일종목에 대하여 동일매출기관의 동일매출일이 접수내역이 있습니다." + "\n해당종목의 접수내역을 확인하여 주시기 바랍니다.");
            return;
        }

        //동일종목에 대한 적용일이 다른 접수내역에 있는지 체크			
        if (scwin.fn_SameIsuOtherAcptYN() > 1) {
            $c.win.alert("동일종목에 대하여 조치일이 다른 접수내역이 있습니다." + "\n각 접수내역의 조치일을 일치시켜 주시기 바랍니다.");
        } else {
            var vTeamleadOrProcs;
            vTeamleadOrProcs = "TEAMLEARD"; //팀장확인된 종목이 있는가 체크
            if (scwin.fn_TeamLeaderOrProcsCnt(vTeamleadOrProcs) > 0) {
                $c.win.alert("동일종목에 대하여 이미 팀장확인된 신청내역이 있습니다." + "\n이 경우 현재 신청내역의 접수처리시 자동으로 처리완료가 됩니다.");
                //팀장확인 처리
                scwin.processGp = "6";
                var confrmDd = dts_List.getCellData(dts_List.getRowPosition(), "TEAMLEADER_CONFRM_DD");
                $c.bns.fn_TeamleadrConfrm1(scwin.vScrenID, trs_Save, confrmDd, scwin.gBndApplId, scwin.vBndListProcsTpCd);
            }
            vTeamleadOrProcs = "PROCS_COMPLT"; //처리완료된 종목이 있는가 체크
            if (scwin.fn_TeamLeaderOrProcsCnt(vTeamleadOrProcs) > 0) {
                $c.win.alert("동일종목에 대하여 이미 처리완료된 신청내역이 있습니다." + "\n이 경우 현재 신청내역의 접수처리시 자동으로 처리완료가 됩니다.");
                //처리완료 처리
                scwin.processGp = '3';
                scwin.fn_ProcsComplt();
            }
        }
    }

    //첨부문서 체크	
    if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '접수')) return;
    var url = "/bns/IsuChgAmt.do?method=processApplAcpt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_GetApplId
 * 설명       : 종목코드별 신청ID를 리턴한다.
 ***********************************************/
scwin.fn_GetApplId = function() {
    var applId = '';
    var returnVal = '';
    for (var i = 0; dts_SalesList.getTotalRow() > i; i++) {
        applId = dts_SalesList.getCellData(i + 1, "BND_APPL_ID");
        returnVal += "'" + applId + "',";
    }
    return returnVal.substring(0, returnVal.length - 1);
};


/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 를 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    //접수, 처리완료 공통 체크
    if (scwin.fn_AcptProcsCheck('Procs') > 0) return;

    // 복수조치 체크
    // 일별금액조정-기타변경, 일별금액조정-월별금액조정은 복수시장조치가 가능하다. 2024.08.23 by no3
    // 아래 함수는 고칠것 없음. TBLD_B_MULTACT_IMPSBL_RULE의 데이터 변경으로 복수시장조치 가능하도록 수정함.
    if ($c.bns.fn_CheckMultActImpsblRuleProcEnd(scwin.vScrenID, dts_Temp, scwin.vIsuCd, scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd2)) > 0) return;

    // 중복시장조치코드에따른 alert
    if (dts_List.getCellData(dts_List.getRowPosition(), "DUP_MKTACT_CD") == "316") {
        $c.win.alert("기타변경 화면과 중복조치가 발생했습니다.\n\"변경 후 상장금액\"을 확인하시기 바랍니다.");
    } else if (dts_List.getCellData(dts_List.getRowPosition(), "DUP_MKTACT_CD") == "301") {
        $c.win.alert("일괄상장 월별금액조정 화면과 중복조치가 발생했습니다.\n\"변경 후 상장금액\"을 확인하시기 바랍니다.");
    }

    //동일종목에 대한 적용일이 다른 접수내역에 있는지 체크
    if (scwin.fn_SameIsuOtherAcptYN() > 1) {
        $c.win.alert("동일종목에 대하여 조치일이 다른 접수내역이 있습니다." + "\n각 접수내역의 조치일을 일치시켜 주시기 바랍니다.");
    }
    var url;
    if (scwin.processGp == '3') {
        if (!confirm("처리완료 하시겠습니까?")) return;
        url = "/bns/IsuChgAmt.do?method=processAcptProcessComplt";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
