/******************************************************************* 
 * 함수명   : fn_TeamleadrConfrm - 사용안함
 * 설명     : 일별금액조정 팀장확인을 처리한다.
 * argument : vScrenID, trsObj, confrmDd, gBndApplIds, vBndListProcsTpCd
 *******************************************************************/
scwin.fn_TeamleadrConfrm = function(vScrenID, trsObj, confrmDd, gBndApplIds, vBndListProcsTpCd) {
    if (confrmDd != "undefined" && confrmDd != '-' && confrmDd != '') {
        if (!window.confirm("이미 팀장확인처리되었습니다. 재처리하실경우 다시 시장지파일이 전송됩니다. \n 팀장확인처리하시겠읍니까?")) return;
    } else {
        if (!window.confirm("팀장확인처리일자가 시장지파일 전송일자입니다. \n 팀장확인처리하시겠읍니까?")) return;
    }
    var url = "/bns/IsuChgAmt.do?method=processTeamleadrConfrm";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&ALL_BND_APPL_ID=" + gBndApplIds;
    url += "&BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    trsObj.Action = $c.lc.fn_encodeNSession(url);
    trsObj.KeyName = "toinb_dataid4";
    trsObj.KeyValue = "JSP(I:pInput=dts_Temp)";
    trsObj.Post();
};


