/****************************************
 * 함수명  	: fn_RowPosPack
 * 설명		: DataSet Reset시 해당 ROW로 이동
 * param		: dts_List
 ****************************************/
scwin.fn_RowPosPack = function(dts_List) {
    var vRow = 0;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if (scwin.objRowPos.ISU_CD == dts_List.getCellData(i, 'ISU_CD') && scwin.objRowPos.STRT_DD == dts_List.getCellData(i, 'STRT_DD')) {
            vRow = i;
            break;
        }
    }
    dts_List.setRowPosition(dts_List.getTotalRow(), 0);
    dts_List.setRowPosition(vRow, 0);
};


/********************************************** 
 * 함수명   : fn_setCheckBoxALL
 * 설명       : 그리드 체크박스 전체선택 또는 전체선택 해제
 ***********************************************/
scwin.fn_setCheckBoxALL = function(grdObj, dtsObj, bCheck) {
    var vcd = "";
    if (bCheck == '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        if (dtsObj.getCellData(i, "PROCS_STAT") != '처리완료' || (dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") != "undefined" && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") != '-' && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") != '')) {
            //처리완료만 팀장확인 대상임
            dtsObj.setCellData(i, "CHK", "F");
        } else {
            dtsObj.setCellData(i, "CHK", vcd);
        }
    }
    grdObj.setBroadcast(true);
};


/**
 * 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 */
