    var DUP_MKTACT_CD = dts_List.getCellData(dts_List.getRowPosition(), "DUP_MKTACT_CD");
    if (DUP_MKTACT_CD != "") {
        edt_AfchgListAmt.ReadOnlyBackColor = "#FF9898";
    } else {
        edt_AfchgListAmt.ReadOnlyBackColor = "#b9d4f7";
    }
    edt_AfchgListAmt.RightMargin = 5;
};
