scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (scwin.vBndListProcsTpCd == 2) {
        $c.cm.CloseWin(rowcount, grd_List2);

        //접수,수정,팀장확인,처리완료 시 해당 ROW로 이동
        if (scwin.objRowPos.ISU_CD != undefined) {
            scwin.fn_RowPosPack(dts_List);
        }
        //반송 시, 신청건수가 1건 이상은 해당 ROW로 이동
        if (scwin.vRetRowApplCnt > 1) {
            dts_List.setRowPosition(scwin.vRetRow, 0);
        }

        // 중복조치건은 그리드 색깔 변경. 2024.08.23
        // 일별금액조정-기타변경, 일별금액조정-월별금액조정  중복조치가 가능
        scwin.fn_ChangeGridBgColor();
    } else {
        $c.cm.CloseWin(rowcount, grd_List1);
    }
};
