scwin.btn_TeamleadrConfrm_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    //objRowPos.STRT_DD = dts_List.NameValue(dts_List.RowPosition, "STRT_DD");
    //objRowPos.ISU_CD = getObjectValue(txb_IsuCd2);
    scwin.processGp = "6";

    //체크된 것 카운팅
    var nTrueCnt = 0;
    for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
        if (dts_List.getCellData(nRow, "CHK") == "T") {
            nTrueCnt++;
        }
    }
    if (nTrueCnt == 0) {
        $c.win.alert("선택된 정보가 없습니다.");
        return false;
    }
    $c.bns.fn_TeamleadrConfrmAll320(scwin.vScrenID, trs_Save, dts_List, scwin.vBndListProcsTpCd, nTrueCnt);
};
scwin.dts_CheckCnt_OnLoadCompleted = function(rowcount) {
    scwin.vCheck_DuplCnt = dts_CheckCnt.getTotalRow();
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "접수"));
    }
    if (scwin.processGp == '3') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "처리완료"));
    }
    if (scwin.processGp == '6') {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "팀장확인"));
    }
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "접수"));
    }
    if (scwin.processGp == '3') {
        $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    }
    if (scwin.processGp == '6') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
    }
    scwin.fn_list_sync();
};
