scwin.dts_DtlInfo_OnColumnChanged = function(row, colid) {
    if (colid == "BND_SALE_TOTAMT" || colid == "REDMPT_AMT") {
        /** 일중 순매출액(화면 자동 계산) */
        if (scwin.vBndListProcsTpCd == 1) {
            $c.stf.setObjectValue(edt_NetSaleAmt, Number($c.stf.getObjectValue(edt_BndSaleTotamt)) - Number($c.stf.getObjectValue(edt_RedmptAmt)));
        }
    }
};
